// ─── File: QueryOrderDemo.java ───
// Executes a pipeline in the logical SQL clause order and shows the alias rule.
package com.bank.order;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class QueryOrderDemo {
    private static final Logger log = Logger.getLogger(QueryOrderDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TxnRepository repo = new TxnRepository();
        QueryOrderService service = new QueryOrderService(repo);

        log.info("=== Alias in WHERE: fails because SELECT runs AFTER WHERE ===");
        try {
            service.aliasInWhereBroken();
        } catch (IllegalStateException ex) {
            log.severe(() -> "Rejected: " + ex.getMessage());
        }

        log.info("=== Correct pipeline: WHERE → GROUP BY → HAVING → SELECT → ORDER → LIMIT ===");
        service.branchTotalsOverThreshold(new BigDecimal("1000"), new BigDecimal("50000"))
            .forEach(r -> log.info(() -> r[0] + " total=Rs." + r[1]));
    }
}

// ─── Would be in model/Txn.java ───
class Txn {
    final String txnId, branch; final BigDecimal amount;
    Txn(String id, String branch, BigDecimal amt) {
            this.txnId = id;
            this.branch = branch
            this.amount = amt;
    }
}

// ─── Would be in repository/TxnRepository.java ───
class TxnRepository {
    List<Txn> findAll() {
        return List.of(
            new Txn("TX1", "Delhi",  new BigDecimal("30000")),
            new Txn("TX2", "Delhi",  new BigDecimal("25000")),
            new Txn("TX3", "Mumbai", new BigDecimal("10000")),
            new Txn("TX4", "Mumbai", new BigDecimal("5000")),
            new Txn("TX5", "Delhi",  new BigDecimal("2000")));
    }
}

// ─── Would be in service/QueryOrderService.java ───
class QueryOrderService {
    private final TxnRepository repo;
    QueryOrderService(TxnRepository repo) { this.repo = repo; }

    // Mimics referencing a SELECT alias in WHERE — not allowed, alias not yet defined.
    void aliasInWhereBroken() {
        // At the WHERE step, only base columns exist. 'gross' is defined in SELECT, later.
        throw new IllegalStateException(
            "column 'gross' does not exist in WHERE (SELECT alias is evaluated later)");
    }

    // Pipeline in logical order: FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER → LIMIT
    List<Object[]> branchTotalsOverThreshold(BigDecimal rowMin, BigDecimal groupMin) {
        // FROM: start with all rows
        List<Txn> rows = repo.findAll();

        // WHERE: row-level filter, base columns only (amount > rowMin)
        List<Txn> filtered = rows.stream()
            .filter(t -> t.amount.compareTo(rowMin) > 0).toList();

        // GROUP BY branch
        Map<String, BigDecimal> grouped = new LinkedHashMap<>();
        for (Txn t : filtered) grouped.merge(t.branch, t.amount, BigDecimal::add);

        // HAVING: group-level filter using the aggregate
        List<Object[]> selected = new ArrayList<>();
        grouped.forEach((branch, total) -> {
            if (total.compareTo(groupMin) > 0)
                selected.add(new Object[]{branch, total}); // SELECT alias 'total'
        });

        // ORDER BY total DESC (alias usable here)
        selected.sort((a, b) -> ((BigDecimal) b[1]).compareTo((BigDecimal) a[1]));

        // LIMIT 5
        return selected.size() > 5 ? selected.subList(0, 5) : selected;
    }
}

